hints.code_snippet:
class Instrument {
  constructor(name, material) {
    this.name = name;
    this.material = material;
  }

  play() {
    return `${this.name} produces a generic sound.`;
  }
}

class StringInstrument extends Instrument {
  constructor(name, material, numberOfStrings) {
    super(name, material);
    this.name = name; 
    this.material = material;
    this.numberOfStrings = numberOfStrings;
  }

  play() {
    const instrumentBaseDescription = `${this.name} made of ${this.material}`; 
    return `${instrumentBaseDescription} is being plucked, producing a melodic sound from its ${this.numberOfStrings} strings.`;
  }
}

class Guitar extends StringInstrument {
  constructor(name, material, numberOfStrings, type) {
    super(name, material, numberOfStrings);
    this.name = name;
    this.material = material;
    this.numberOfStrings = numberOfStrings;
    this.type = type;
  }

  play() {
    super.play(); 
    return `The ${this.type} ${this.name} is being strummed melodically across its ${this.numberOfStrings} strings.`;
  }
}

